-- Sistema de Gestión y Control de Ganado
-- Datos demostrativos para importación desde phpMyAdmin.
-- Requiere haber importado primero sql/schema.sql de la versión 1.1.0.
--
-- ATENCIÓN: reemplaza todos los datos operativos. Conserva usuarios, bitácora
-- de accesos y reglas financieras/productivas. No contiene credenciales.

SET NAMES utf8mb4;
SET @previous_foreign_key_checks := @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

DELETE FROM `closing_audit`;
DELETE FROM `closing_movements`;
DELETE FROM `monthly_valuations`;
DELETE FROM `monthly_closing_groups`;
DELETE FROM `monthly_closings`;
DELETE FROM `transfer_ledger_entries`;
DELETE FROM `sales`;
DELETE FROM `transfers`;
DELETE FROM `labor_entries`;
DELETE FROM `warehouse_movements`;
DELETE FROM `costs`;
DELETE FROM `animal_events`;
DELETE FROM `weights`;
DELETE FROM `weight_import_batches`;
DELETE FROM `animal_history`;
DELETE FROM `animals`;
DELETE FROM `employees`;
DELETE FROM `warehouse_products`;
DELETE FROM `activities`;
DELETE FROM `locations`;
DELETE FROM `cattle_groups`;


-- Relacionar el escenario con la regla activa de la instalación destino.
SET @demo_rule_set_id := COALESCE(
  (SELECT `id` FROM `rule_sets` WHERE `status` = 'ACTIVE' ORDER BY `effective_from` DESC, `id` DESC LIMIT 1),
  (SELECT `id` FROM `rule_sets` ORDER BY `id` DESC LIMIT 1)
);
UPDATE `transfers` SET `rule_set_id` = @demo_rule_set_id WHERE `rule_set_id` IS NOT NULL;
UPDATE `monthly_closings` SET `rule_set_id` = @demo_rule_set_id WHERE `rule_set_id` IS NOT NULL;
UPDATE `monthly_valuations` SET `rule_set_id` = @demo_rule_set_id WHERE `rule_set_id` IS NOT NULL;
UPDATE `animal_history` SET `rule_set_id` = @demo_rule_set_id WHERE `rule_set_id` IS NOT NULL;

COMMIT;
SET FOREIGN_KEY_CHECKS = @previous_foreign_key_checks;
